const surfX = -1.55;
const heatX = 2.05;
const SX = 1.45, SZ = 1.15, SY = 1.75 / 70;
const HX = 1.16, HY = 1.16;
const N = 80;
const markerData = [
  { name: 'pale gray-white', p0: 1.60, p1: -0.80, color: 0xcfd8da },
  { name: 'light cyan', p0: 0.40, p1: 0.20, color: 0xa7e7e6 },
];
let current = { p0: 0.88, p1: 0.50 };
let viewModeValue = '3D surface';
let lr = 0.03;
let gdAnimating = false;
let gdFrame = 0;
let gdPath = [];

document.getElementById('btnReset').style.display = '';

const surfaceGroup = new THREE.Group();
surfaceGroup.position.set(surfX, 0, 0);
scene.add(surfaceGroup);

const heatmapGroup = new THREE.Group();
heatmapGroup.position.set(heatX, 0.55, 0);
scene.add(heatmapGroup);

function loss(p0, p1) {
  const d0 = p0 - 0.92, d1 = p1 - 0.52;
  return 0.95 * (12 * d0 * d0 + 8 * d0 * d1 + 24 * d1 * d1);
}
function grad(p0, p1) {
  const d0 = p0 - 0.92, d1 = p1 - 0.52;
  return {
    g0: 0.95 * (24 * d0 + 8 * d1),
    g1: 0.95 * (8 * d0 + 48 * d1)
  };
}
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function colorForLoss(L) {
  const t = clamp(L / 70, 0, 1);
  const stops = [
    { t: 0.00, c: new THREE.Color('#260700') },
    { t: 0.42, c: new THREE.Color('#6b2318') },
    { t: 0.72, c: new THREE.Color('#c06b55') },
    { t: 1.00, c: new THREE.Color('#ffd6a5') },
  ];
  for (let i = 0; i < stops.length - 1; i++) {
    if (t <= stops[i + 1].t) {
      const u = (t - stops[i].t) / (stops[i + 1].t - stops[i].t);
      return stops[i].c.clone().lerp(stops[i + 1].c, u);
    }
  }
  return stops[stops.length - 1].c.clone();
}
function surfLocal(p0, p1, lift = 0) {
  return new THREE.Vector3((p0 - 1) * SX, loss(p0, p1) * SY + lift, p1 * SZ);
}
function heatLocal(p0, p1, z = 0.025) {
  return new THREE.Vector3((p0 - 1) * HX, -p1 * HY, z);
}
function groupWorld(group, local) {
  group.updateMatrixWorld(true);
  return local.clone().applyMatrix4(group.matrixWorld);
}

const surfPositions = [];
const surfColors = [];
const surfIndices = [];
for (let j = 0; j <= N; j++) {
  const p1 = -1 + 2 * j / N;
  for (let i = 0; i <= N; i++) {
    const p0 = 2 * i / N;
    const L = loss(p0, p1);
    const v = surfLocal(p0, p1, 0);
    const c = colorForLoss(L);
    surfPositions.push(v.x, v.y, v.z);
    surfColors.push(c.r, c.g, c.b);
  }
}
for (let j = 0; j < N; j++) {
  for (let i = 0; i < N; i++) {
    const a = j * (N + 1) + i, b = a + 1, c = a + (N + 1), d2 = c + 1;
    surfIndices.push(a, c, b, b, c, d2);
  }
}
const surfGeom = new THREE.BufferGeometry();
surfGeom.setAttribute('position', new THREE.Float32BufferAttribute(surfPositions, 3));
surfGeom.setAttribute('color', new THREE.Float32BufferAttribute(surfColors, 3));
surfGeom.setIndex(surfIndices);
surfGeom.computeVertexNormals();
const surfMesh = new THREE.Mesh(surfGeom, new THREE.MeshBasicMaterial({
  vertexColors: true,
  side: THREE.DoubleSide
}));
surfaceGroup.add(surfMesh);
registerInteractive(surfMesh, {
  title: 'Convex loss surface',
  tooltip: 'Least-squares loss bowl',
  body: 'The quadratic loss has a single global minimum near φ₀=0.92, φ₁=0.52. The orange-peach regions are high loss; the dark maroon basin is low loss.'
});

const gridVerts = [];
for (let j = 0; j <= N; j++) {
  for (let i = 0; i < N; i++) {
    const p1 = -1 + 2 * j / N;
    const a = surfLocal(2 * i / N, p1, 0.006);
    const b = surfLocal(2 * (i + 1) / N, p1, 0.006);
    gridVerts.push(a.x, a.y, a.z, b.x, b.y, b.z);
  }
}
for (let i = 0; i <= N; i++) {
  for (let j = 0; j < N; j++) {
    const p0 = 2 * i / N;
    const a = surfLocal(p0, -1 + 2 * j / N, 0.006);
    const b = surfLocal(p0, -1 + 2 * (j + 1) / N, 0.006);
    gridVerts.push(a.x, a.y, a.z, b.x, b.y, b.z);
  }
}
const surfGrid = new THREE.LineSegments(
  new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(gridVerts, 3)),
  new THREE.LineBasicMaterial({ color: 0xffead4, transparent: true, opacity: 0.20 })
);
surfaceGroup.add(surfGrid);

function lineSegsFromPairs(pairs, color, opacity = 1) {
  const arr = [];
  for (const [a, b] of pairs) arr.push(a.x, a.y, a.z, b.x, b.y, b.z);
  return new THREE.LineSegments(
    new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(arr, 3)),
    new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
}

const axisPairs = [];
axisPairs.push([new THREE.Vector3(-SX, 0, SZ), new THREE.Vector3(SX, 0, SZ)]);
axisPairs.push([new THREE.Vector3(-SX, 0, -SZ), new THREE.Vector3(-SX, 0, SZ)]);
axisPairs.push([new THREE.Vector3(-SX, 0, -SZ), new THREE.Vector3(-SX, 70 * SY, -SZ)]);
for (let p0 = 0; p0 <= 2.001; p0 += 0.5) {
  const x = (p0 - 1) * SX;
  axisPairs.push([new THREE.Vector3(x, 0, SZ), new THREE.Vector3(x, 0.035, SZ)]);
}
for (let p1 = -1; p1 <= 1.001; p1 += 0.5) {
  const z = p1 * SZ;
  axisPairs.push([new THREE.Vector3(-SX, 0, z), new THREE.Vector3(-SX - 0.04, 0, z)]);
}
for (let L = 0; L <= 70; L += 10) {
  const y = L * SY;
  axisPairs.push([new THREE.Vector3(-SX, y, -SZ), new THREE.Vector3(-SX - 0.05, y, -SZ)]);
}
surfaceGroup.add(lineSegsFromPairs(axisPairs, 0x111111, 1));

const bgPairs = [];
for (let i = 0; i <= 10; i++) {
  const x = -SX + 2 * SX * i / 10;
  bgPairs.push([new THREE.Vector3(x, 0, -SZ), new THREE.Vector3(x, 0, SZ)]);
  bgPairs.push([new THREE.Vector3(x, 0, -SZ), new THREE.Vector3(x, 70 * SY, -SZ)]);
}
for (let j = 0; j <= 10; j++) {
  const z = -SZ + 2 * SZ * j / 10;
  bgPairs.push([new THREE.Vector3(-SX, 0, z), new THREE.Vector3(SX, 0, z)]);
}
for (let k = 0; k <= 7; k++) {
  const y = 70 * SY * k / 7;
  bgPairs.push([new THREE.Vector3(-SX, y, -SZ), new THREE.Vector3(SX, y, -SZ)]);
}
surfaceGroup.add(lineSegsFromPairs(bgPairs, 0xbdbdbd, 0.55));

const markerGeom = new THREE.SphereGeometry(0.07, 24, 16);
const fixed3DMarkers = [];
const fixed2DMarkers = [];
for (const m of markerData) {
  const s = new THREE.Mesh(markerGeom, new THREE.MeshBasicMaterial({ color: m.color }));
  s.position.copy(surfLocal(m.p0, m.p1, 0.07));
  surfaceGroup.add(s);
  fixed3DMarkers.push(s);
  registerInteractive(s, { title: m.name + ' parameter', tooltip: 'Example parameter setting', body: `φ₀=${m.p0.toFixed(2)}, φ₁=${m.p1.toFixed(2)}, L=${loss(m.p0, m.p1).toFixed(2)}` });
}

const active3D = new THREE.Mesh(markerGeom, new THREE.MeshBasicMaterial({ color: 0x23877e }));
surfaceGroup.add(active3D);
registerInteractive(active3D, { title: 'Current parameter', tooltip: 'Drag the teal marker', body: 'This draggable point chooses the intercept and slope used as the gradient-descent starting point.' });

const heatCanvas = document.createElement('canvas');
heatCanvas.width = 512;
heatCanvas.height = 512;
const hctx = heatCanvas.getContext('2d');
const img = hctx.createImageData(512, 512);
for (let y = 0; y < 512; y++) {
  const p1 = -1 + 2 * y / 511;
  for (let x = 0; x < 512; x++) {
    const p0 = 2 * x / 511;
    const c = colorForLoss(loss(p0, p1));
    const idx = 4 * (y * 512 + x);
    img.data[idx] = Math.round(c.r * 255);
    img.data[idx + 1] = Math.round(c.g * 255);
    img.data[idx + 2] = Math.round(c.b * 255);
    img.data[idx + 3] = 255;
  }
}
hctx.putImageData(img, 0, 0);
const heatTex = new THREE.CanvasTexture(heatCanvas);
heatTex.colorSpace = THREE.SRGBColorSpace;
const heatPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(2 * HX, 2 * HY),
  new THREE.MeshBasicMaterial({ map: heatTex, side: THREE.DoubleSide })
);
heatmapGroup.add(heatPlane);
registerInteractive(heatPlane, {
  title: 'Top-down heatmap',
  tooltip: 'Loss as color and contours',
  body: 'This square shows the same loss landscape from above: φ₀ runs left to right, and φ₁ is inverted so −1 is at the top.'
});

const heatBorderPairs = [
  [new THREE.Vector3(-HX, -HY, 0.035), new THREE.Vector3(HX, -HY, 0.035)],
  [new THREE.Vector3(HX, -HY, 0.035), new THREE.Vector3(HX, HY, 0.035)],
  [new THREE.Vector3(HX, HY, 0.035), new THREE.Vector3(-HX, HY, 0.035)],
  [new THREE.Vector3(-HX, HY, 0.035), new THREE.Vector3(-HX, -HY, 0.035)],
];
for (let t = 0; t <= 2.001; t += 0.2) {
  const x = (t - 1) * HX;
  heatBorderPairs.push([new THREE.Vector3(x, -HY, 0.04), new THREE.Vector3(x, -HY - (Math.abs(t - Math.round(t)) < 0.02 ? 0.07 : 0.035), 0.04)]);
}
for (let p = -1; p <= 1.001; p += 0.2) {
  const y = -p * HY;
  heatBorderPairs.push([new THREE.Vector3(-HX, y, 0.04), new THREE.Vector3(-HX - (Math.abs(p - Math.round(p)) < 0.02 ? 0.07 : 0.035), y, 0.04)]);
}
heatmapGroup.add(lineSegsFromPairs(heatBorderPairs, 0x111111, 1));

function makeContours() {
  const pairs = [];
  const n = 110;
  const levels = [];
  for (let L = 5; L <= 70; L += 5) levels.push(L);
  function pt(i, j) {
    const p0 = 2 * i / n;
    const p1 = -1 + 2 * j / n;
    return { p0, p1, v: loss(p0, p1), x: (p0 - 1) * HX, y: -p1 * HY };
  }
  function cross(a, b, lev) {
    const u = (lev - a.v) / (b.v - a.v);
    return new THREE.Vector3(a.x + (b.x - a.x) * u, a.y + (b.y - a.y) * u, 0.055);
  }
  for (const lev of levels) {
    for (let j = 0; j < n; j++) {
      for (let i = 0; i < n; i++) {
        const tl = pt(i, j), tr = pt(i + 1, j), br = pt(i + 1, j + 1), bl = pt(i, j + 1);
        const hits = [];
        if ((tl.v - lev) * (tr.v - lev) < 0) hits.push(cross(tl, tr, lev));
        if ((tr.v - lev) * (br.v - lev) < 0) hits.push(cross(tr, br, lev));
        if ((br.v - lev) * (bl.v - lev) < 0) hits.push(cross(br, bl, lev));
        if ((bl.v - lev) * (tl.v - lev) < 0) hits.push(cross(bl, tl, lev));
        if (hits.length === 2) pairs.push([hits[0], hits[1]]);
        if (hits.length === 4) {
          pairs.push([hits[0], hits[1]]);
          pairs.push([hits[2], hits[3]]);
        }
      }
    }
  }
  return lineSegsFromPairs(pairs, 0x7a7a7a, 0.42);
}
heatmapGroup.add(makeContours());

const circleGeom = new THREE.CircleGeometry(0.075, 36);
for (const m of markerData) {
  const c = new THREE.Mesh(circleGeom, new THREE.MeshBasicMaterial({ color: m.color, side: THREE.DoubleSide }));
  c.position.copy(heatLocal(m.p0, m.p1, 0.075));
  heatmapGroup.add(c);
  fixed2DMarkers.push(c);
}
const active2D = new THREE.Mesh(circleGeom, new THREE.MeshBasicMaterial({ color: 0x23877e, side: THREE.DoubleSide }));
heatmapGroup.add(active2D);

const path3DLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x24d4c8, linewidth: 2 }));
surfaceGroup.add(path3DLine);
const path2DLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x24d4c8, linewidth: 2 }));
heatmapGroup.add(path2DLine);
const step3DGroup = new THREE.Group();
surfaceGroup.add(step3DGroup);
const step2DGroup = new THREE.Group();
heatmapGroup.add(step2DGroup);

const dragPlane3D = new THREE.Mesh(
  new THREE.PlaneGeometry(2 * SX, 2 * SZ),
