const allGroupLabels = [];
const surfaceLabels = [];
const heatLabels = [];
function addGroupLabel(group, local, html, opts, bucket) {
  const entry = addLabel(html, groupWorld(group, local), opts || {});
  const obj = { group, local: local.clone(), entry };
  allGroupLabels.push(obj);
  bucket.push(obj);
  return obj;
}
function updateGroupLabels() {
  for (const g of allGroupLabels) g.entry.pos.copy(groupWorld(g.group, g.local));
}
function setBucketVisible(bucket, on) {
  for (const g of bucket) g.entry.div.style.visibility = on ? 'visible' : 'hidden';
}

addGroupLabel(surfaceGroup, new THREE.Vector3(-1.88, 2.06, -1.25), 'a)', { fontSize: '34px' }, surfaceLabels);
addGroupLabel(heatmapGroup, new THREE.Vector3(-1.50, 1.43, 0.08), 'b)', { fontSize: '34px' }, heatLabels);

for (const p0 of [0, 1, 2]) addGroupLabel(surfaceGroup, new THREE.Vector3((p0 - 1) * SX, -0.10, SZ + 0.13), p0.toFixed(1), { color: '#808080', fontSize: '13px' }, surfaceLabels);
for (const p1 of [-1, 0, 1]) addGroupLabel(surfaceGroup, new THREE.Vector3(-SX - 0.17, -0.08, p1 * SZ), p1.toFixed(1), { color: '#808080', fontSize: '13px' }, surfaceLabels);
for (let L = 0; L <= 70; L += 10) addGroupLabel(surfaceGroup, new THREE.Vector3(-SX - 0.15, L * SY, -SZ - 0.04), String(L), { color: '#808080', fontSize: '13px' }, surfaceLabels);
addGroupLabel(surfaceGroup, new THREE.Vector3(0.30, -0.24, SZ + 0.22), 'Intercept, <i>&phi;</i><sub>0</sub>', { fontSize: '25px' }, surfaceLabels);
addGroupLabel(surfaceGroup, new THREE.Vector3(-SX - 0.32, -0.18, 0.10), 'Slope, <i>&phi;</i><sub>1</sub>', { fontSize: '25px' }, surfaceLabels);
addGroupLabel(surfaceGroup, new THREE.Vector3(-SX - 0.43, 0.96, -SZ - 0.08), 'Loss, <i>L</i>[<i>&phi;</i>]', { fontSize: '25px' }, surfaceLabels);

addGroupLabel(heatmapGroup, new THREE.Vector3(0, HY + 0.22, 0.08), 'Loss, <i>L</i>[<i>&phi;</i>]', { fontSize: '24px' }, heatLabels);
for (const p0 of [0, 1, 2]) addGroupLabel(heatmapGroup, new THREE.Vector3((p0 - 1) * HX, -HY - 0.13, 0.08), p0.toFixed(1), { color: '#808080', fontSize: '16px' }, heatLabels);
for (const p1 of [-1, 0, 1]) addGroupLabel(heatmapGroup, new THREE.Vector3(-HX - 0.13, -p1 * HY, 0.08), p1.toFixed(1), { color: '#808080', fontSize: '16px' }, heatLabels);
addGroupLabel(heatmapGroup, new THREE.Vector3(0.22, -HY - 0.31, 0.08), 'Intercept, <i>&phi;</i><sub>0</sub>', { fontSize: '24px' }, heatLabels);
addGroupLabel(heatmapGroup, new THREE.Vector3(-HX - 0.33, 0.12, 0.08), 'Slope, <i>&phi;</i><sub>1</sub>', { fontSize: '24px' }, heatLabels);

const floatingReadoutLabel = addGroupLabel(surfaceGroup, new THREE.Vector3(0, 0, 0), '', {
  fontSize: '12px',
  background: 'rgba(255,255,255,0.82)',
  color: '#111'
}, surfaceLabels);

function clearSteps(group) {
  while (group.children.length) {
    const c = group.children.pop();
    c.geometry?.dispose?.();
    if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
    else c.material?.dispose?.();
  }
}
function computePath(startP0 = current.p0, startP1 = current.p1) {
  const pts = [{ p0: startP0, p1: startP1 }];
  let p0 = startP0, p1 = startP1;
  for (let k = 0; k < 38; k++) {
    const g = grad(p0, p1);
    const norm = Math.hypot(g.g0, g.g1);
    if (norm < 0.012) break;
    p0 -= lr * g.g0;
    p1 -= lr * g.g1;
    pts.push({ p0, p1 });
    if (Math.abs(p0) > 4 || Math.abs(p1) > 4) break;
  }
  return pts;
}
function rebuildPath(revealCount = Infinity) {
  gdPath = computePath();
  const shown = gdPath.slice(0, Math.min(gdPath.length, revealCount));
  const pts3 = shown.map(p => surfLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.105));
  path3DLine.geometry.dispose();
  path3DLine.geometry = new THREE.BufferGeometry().setFromPoints(pts3);
  const pts2 = shown.map(p => heatLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.105));
  path2DLine.geometry.dispose();
  path2DLine.geometry = new THREE.BufferGeometry().setFromPoints(pts2);
  clearSteps(step3DGroup);
  clearSteps(step2DGroup);
  for (let i = 0; i < shown.length; i++) {
    const p = shown[i];
    const out = p.p0 < 0 || p.p0 > 2 || p.p1 < -1 || p.p1 > 1;
    const mat3 = new THREE.MeshBasicMaterial({ color: out ? 0xffd6a5 : 0x24d4c8, transparent: true, opacity: out ? 0.35 : 0.95 });
    const m3 = new THREE.Mesh(new THREE.SphereGeometry(0.027, 12, 8), mat3);
    m3.position.copy(surfLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.125));
    step3DGroup.add(m3);
    const mat2 = new THREE.MeshBasicMaterial({ color: out ? 0xffd6a5 : 0x24d4c8, transparent: true, opacity: out ? 0.35 : 0.95, side: THREE.DoubleSide });
    const m2 = new THREE.Mesh(new THREE.CircleGeometry(0.026, 16), mat2);
    m2.position.copy(heatLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.125));
    step2DGroup.add(m2);
  }
}
function updateCurrent(skipPath = false) {
  const L = loss(current.p0, current.p1);
  active3D.position.copy(surfLocal(current.p0, current.p1, 0.08));
  active2D.position.copy(heatLocal(current.p0, current.p1, 0.13));
  document.getElementById('paramReadout').innerHTML =
    `φ₀=${current.p0.toFixed(3)}<br>φ₁=${current.p1.toFixed(3)}<br>L[φ]=${L.toFixed(3)}`;
  floatingReadoutLabel.local.copy(surfLocal(current.p0, current.p1, 0.30));
  floatingReadoutLabel.entry.div.innerHTML = `&phi;<sub>0</sub>=${current.p0.toFixed(2)}, &phi;<sub>1</sub>=${current.p1.toFixed(2)}<br><i>L</i>=${L.toFixed(2)}`;
  updateGroupLabels();
  if (!skipPath) rebuildPath();
}
updateCurrent();

function poseCamera(target, dist, azDeg, elDeg) {
  const az = THREE.MathUtils.degToRad(azDeg), el = THREE.MathUtils.degToRad(elDeg);
  const dir = new THREE.Vector3(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el));
  camera.position.copy(dir.multiplyScalar(dist).add(new THREE.Vector3(target[0], target[1], target[2])));
  controls.target.set(target[0], target[1], target[2]);
  camera.lookAt(controls.target);
  camera.near = 0.01;
  camera.far = 1000;
  camera.updateProjectionMatrix();
  controls.update();
}
function applyViewMode(mode) {
  viewModeValue = mode;
  for (const b of document.querySelectorAll('#viewMode button')) b.classList.toggle('active', b.dataset.view === mode);
  surfaceGroup.visible = mode !== 'Heatmap';
  heatmapGroup.visible = mode !== '3D surface';
  setBucketVisible(surfaceLabels, mode !== 'Heatmap');
  setBucketVisible(heatLabels, mode !== '3D surface');
  controls.enableRotate = mode !== 'Heatmap';
  controls.enabled = mode !== 'Heatmap';
  if (mode === '3D surface') {
    poseCamera([surfX, 0.70, 0.05], 4.9, 45, 28);
  } else if (mode === 'Heatmap') {
    camera.position.set(heatX, 0.55, 5.25);
    controls.target.set(heatX, 0.55, 0);
    camera.lookAt(controls.target);
    camera.near = 0.01;
    camera.far = 1000;
    camera.updateProjectionMatrix();
    controls.update();
  } else {
    controls.enabled = true;
    controls.enableRotate = true;
    poseCamera([0.20, 0.70, 0.05], 6.0, 38, 24);
  }
}
applyViewMode('3D surface');

document.querySelectorAll('#viewMode button').forEach(btn => {
  btn.addEventListener('click', () => applyViewMode(btn.dataset.view));
});
document.getElementById('learningRate').addEventListener('input', e => {
  lr = Number(e.target.value);
  document.getElementById('lrVal').textContent = lr.toFixed(3);
  gdAnimating = false;
  rebuildPath();
});

document.getElementById('gradientDescentRun').addEventListener('click', () => {
  gdAnimating = true;
  gdFrame = 1;
  rebuildPath(1);
});

function tickGD() {
  if (!gdAnimating) return;
  gdFrame += 0.075;
  const idx = Math.min(gdPath.length - 1, Math.floor(gdFrame));
  if (gdPath[idx]) {
    current.p0 = clamp(gdPath[idx].p0, 0, 2);
    current.p1 = clamp(gdPath[idx].p1, -1, 1);
    updateCurrent(true);
    rebuildPath(idx + 1);
  }
  if (idx >= gdPath.length - 1) gdAnimating = false;
  requestAnimationFrame(tickGD);
}
document.getElementById('gradientDescentRun').addEventListener('click', () => requestAnimationFrame(tickGD));

const dragRay = new THREE.Raycaster();
const dragNdc = new THREE.Vector2();
let dragging = false;
function ndcFromEvent(e) {
  const rect = canvas.getBoundingClientRect();
  dragNdc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
