  const targets = [];
  if (surfaceGroup.visible) targets.push(dragPlane3D);
  if (heatmapGroup.visible) targets.push(dragPlane2D);
  const hits = dragRay.intersectObjects(targets, false);
  if (!hits.length) return null;
  const h = hits[0];
  if (h.object === dragPlane3D) {
    const loc = surfaceGroup.worldToLocal(h.point.clone());
    return { p0: clamp(loc.x / SX + 1, 0, 2), p1: clamp(loc.z / SZ, -1, 1) };
  } else {
    const loc = heatmapGroup.worldToLocal(h.point.clone());
    return { p0: clamp(loc.x / HX + 1, 0, 2), p1: clamp(-loc.y / HY, -1, 1) };
