document.getElementById('btnReset').style.display = '';

const surfX = -1.42;
const heatX = 1.55;
const SX = 1.34, SZ = 1.07, SY = 1.72 / 70;
const HX = 1.12, HY = 1.12;
const N = 80;
const MAX_L = 70;
const markerData = [
