function loss(p0, p1) {
  const d0 = p0 - 0.92, d1 = p1 - 0.52;
  return 0.95 * (12 * d0 * d0 + 8 * d0 * d1 + 24 * d1 * d1);
}
function grad(p0, p1) {
  const d0 = p0 - 0.92, d1 = p1 - 0.52;
