const heatBorderPairs = [
  [new THREE.Vector3(-HX, -HY, 0.045), new THREE.Vector3(HX, -HY, 0.045)],
  [new THREE.Vector3(HX, -HY, 0.045), new THREE.Vector3(HX, HY, 0.045)],
  [new THREE.Vector3(HX, HY, 0.045), new THREE.Vector3(-HX, HY, 0.045)],
  [new THREE.Vector3(-HX, HY, 0.045), new THREE.Vector3(-HX, -HY, 0.045)],
