for (let t = 0; t <= 2.001; t += 0.2) {
  const x = (t - 1) * HX;
  const major = Math.abs(t - Math.round(t)) < 0.02;
  heatBorderPairs.push([new THREE.Vector3(x, -HY, 0.055), new THREE.Vector3(x, -HY - (major ? 0.075 : 0.038), 0.055)]);
