  const y = -p * HY;
  const major = Math.abs(p - Math.round(p)) < 0.02;
  heatBorderPairs.push([new THREE.Vector3(-HX, y, 0.055), new THREE.Vector3(-HX - (major ? 0.075 : 0.038), y, 0.055)]);
}
heatmapGroup.add(makeLineSegs(heatBorderPairs, 0x111111, 1));

function makeContours() {
  const pairs = [];
  const n = 118;
  const levels = [];
  for (let L = 5; L <= 70; L += 5) levels.push(L);
  function pt(i, j) {
    const p0 = 2 * i / n;
    const p1 = -1 + 2 * j / n;
    return { p0, p1, v: loss(p0, p1), x: (p0 - 1) * HX, y: -p1 * HY };
  }
  function cross(a, b, lev) {
    const u = clamp((lev - a.v) / (b.v - a.v), 0, 1);
    return new THREE.Vector3(a.x + (b.x - a.x) * u, a.y + (b.y - a.y) * u, 0.065);
