    for (let j = 0; j < n; j++) {
      for (let i = 0; i < n; i++) {
        const tl = pt(i, j), tr = pt(i + 1, j), br = pt(i + 1, j + 1), bl = pt(i, j + 1);
        const hits = [];
        if ((tl.v - lev) * (tr.v - lev) < 0) hits.push(cross(tl, tr, lev));
        if ((tr.v - lev) * (br.v - lev) < 0) hits.push(cross(tr, br, lev));
        if ((br.v - lev) * (bl.v - lev) < 0) hits.push(cross(br, bl, lev));
        if ((bl.v - lev) * (tl.v - lev) < 0) hits.push(cross(bl, tl, lev));
