}

addGroupLabel(surfaceGroup, new THREE.Vector3(-1.70, 2.22, -1.25), 'a)', { fontSize: '34px' }, surfaceLabels);
addGroupLabel(heatmapGroup, new THREE.Vector3(-1.48, 1.36, 0.10), 'b)', { fontSize: '34px' }, heatLabels);

for (const p0 of [0, 1, 2]) addGroupLabel(surfaceGroup, new THREE.Vector3((p0 - 1) * SX, -0.12, SZ + 0.14), p0.toFixed(1), { color: '#808080', fontSize: '13px' }, surfaceLabels);
