    const m3 = new THREE.Mesh(
      new THREE.SphereGeometry(0.026, 12, 8),
      new THREE.MeshBasicMaterial({ color: out ? 0xffd6a5 : 0x24d4c8, transparent: true, opacity: out ? 0.35 : 0.96 })
