function makeContours() {
  const pairs = [];
  const n = 118;
  const levels = [];
  for (let L = 5; L <= 70; L += 5) levels.push(L);
  function pt(i, j) {
    const p0 = 2 * i / n;
    const p1 = -1 + 2 * j / n;
    return { p0, p1, v: loss(p0, p1), x: (p0 - 1) * HX, y: -p1 * HY };
  }
  function cross(a, b, lev) {
    const u = clamp((lev - a.v) / (b.v - a.v), 0, 1);
    return new THREE.Vector3(a.x + (b.x - a.x) * u, a.y + (b.y - a.y) * u, 0.065);
  }
  for (const lev of levels) {
    for (let j = 0; j < n; j++) {
      for (let i = 0; i < n; i++) {
        const tl = pt(i, j), tr = pt(i + 1, j), br = pt(i + 1, j + 1), bl = pt(i, j + 1);
        const hits = [];
        if ((tl.v - lev) * (tr.v - lev) < 0) hits.push(cross(tl, tr, lev));
        if ((tr.v - lev) * (br.v - lev) < 0) hits.push(cross(tr, br, lev));
        if ((br.v - lev) * (bl.v - lev) < 0) hits.push(cross(br, bl, lev));
        if ((bl.v - lev) * (tl.v - lev) < 0) hits.push(cross(bl, tl, lev));
        if (hits.length === 2) pairs.push([hits[0], hits[1]]);
        if (hits.length === 4) {
          pairs.push([hits[0], hits[1]]);
          pairs.push([hits[2], hits[3]]);
        }
      }
    }
  }
  return makeLineSegs(pairs, 0x7a7a7a, 0.42);
}
