  const pts2 = shown.map(p => heatLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.125));
  path2DLine.geometry.dispose();
  path2DLine.geometry = new THREE.BufferGeometry().setFromPoints(pts2);
  clearSteps(step3DGroup);
  clearSteps(step2DGroup);
  for (let i = 0; i < shown.length; i++) {
    const p = shown[i];
    const out = p.p0 < 0 || p.p0 > 2 || p.p1 < -1 || p.p1 > 1;
    const m3 = new THREE.Mesh(
      new THREE.SphereGeometry(0.026, 12, 8),
      new THREE.MeshBasicMaterial({ color: out ? 0xffd6a5 : 0x24d4c8, transparent: true, opacity: out ? 0.35 : 0.96 })
    );
    m3.position.copy(surfLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.135));
    step3DGroup.add(m3);
    const m2 = new THREE.Mesh(
