function poseCamera(target, dist, azDeg, elDeg, zoom = 1) {
  const az = THREE.MathUtils.degToRad(azDeg), el = THREE.MathUtils.degToRad(elDeg);
  const dir = new THREE.Vector3(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el)).normalize();
  camera.position.copy(dir.multiplyScalar(dist).add(new THREE.Vector3(target[0], target[1], target[2])));
  controls.target.set(target[0], target[1], target[2]);
  camera.up.set(0, 1, 0);
  camera.lookAt(controls.target);
  camera.near = 0.01;
  camera.far = 1000;
  camera.zoom = zoom;
  camera.updateProjectionMatrix();
  controls.update();
}
function poseHeatmapCamera() {
  heatmapGroup.updateMatrixWorld(true);
  const center = groupWorld(heatmapGroup, new THREE.Vector3(0, 0, 0.05));
  const normal = new THREE.Vector3(0, 0, 1).transformDirection(heatmapGroup.matrixWorld).normalize();
  camera.position.copy(center).addScaledVector(normal, 3.35);
  controls.target.copy(center);
  camera.up.set(0, 1, 0);
  camera.lookAt(center);
  camera.near = 0.01;
  camera.far = 1000;
  camera.zoom = 1.05;
  camera.updateProjectionMatrix();
  controls.update();
}
