function loss(p0, p1) {
  const d0 = p0 - 0.92;
  const d1 = p1 - 0.52;
  return 0.90 * (10.0 * d0 * d0 + 12.0 * d0 * d1 + 18.0 * d1 * d1);
}
function grad(p0, p1) {
  const d0 = p0 - 0.92;
  const d1 = p1 - 0.52;
  return {
    g0: 0.90 * (20.0 * d0 + 12.0 * d1),
    g1: 0.90 * (12.0 * d0 + 36.0 * d1)
  };
}
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

function colorForLoss(L) {
  const t = clamp(L / MAX_L, 0, 1);
  const stops = [
    { t: 0.00, c: new THREE.Color('#160300') },
    { t: 0.18, c: new THREE.Color('#2d0803') },
    { t: 0.42, c: new THREE.Color('#5a1912') },
    { t: 0.68, c: new THREE.Color('#9a4b3d') },
    { t: 0.86, c: new THREE.Color('#de906f') },
    { t: 1.00, c: new THREE.Color('#ffe1ae') },
  ];
  for (let i = 0; i < stops.length - 1; i++) {
    if (t <= stops[i + 1].t) {
      const u = (t - stops[i].t) / (stops[i + 1].t - stops[i].t);
      return stops[i].c.clone().lerp(stops[i + 1].c, u);
    }
  }
  return stops[stops.length - 1].c.clone();
}
function surfLocal(p0, p1, lift = 0) {
  return new THREE.Vector3((p0 - 1) * SX, loss(p0, p1) * SY + lift, p1 * SZ);
}
function heatLocal(p0, p1, z = 0.03) {
  return new THREE.Vector3((p0 - 1) * HX, -p1 * HY, z);
}
function groupWorld(group, local) {
  group.updateMatrixWorld(true);
  return local.clone().applyMatrix4(group.matrixWorld);
}
function makeLineSegs(pairs, color, opacity = 1, linewidth = 1) {
  const arr = [];
  for (const [a, b] of pairs) arr.push(a.x, a.y, a.z, b.x, b.y, b.z);
  return new THREE.LineSegments(
    new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(arr, 3)),
    new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity, linewidth })
  );
}

