  const p1 = -1 + 2 * j / N;
  for (let i = 0; i <= N; i++) {
    const p0 = 2 * i / N;
    const L = loss(p0, p1);
    const v = surfLocal(p0, p1, 0);
    const c = colorForLoss(L);
    surfPositions.push(v.x, v.y, v.z);
    surfColors.push(c.r, c.g, c.b);
  }
}
for (let j = 0; j < N; j++) {
  for (let i = 0; i < N; i++) {
    const a = j * (N + 1) + i;
    const b = a + 1;
    const c = a + (N + 1);
    const d2 = c + 1;
    surfIndices.push(a, c, b, b, c, d2);
  }
}
