function clearSteps(group) {
  while (group.children.length) {
    const c = group.children.pop();
    c.geometry?.dispose?.();
    if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
    else c.material?.dispose?.();
  }
}
function computePath(startP0 = current.p0, startP1 = current.p1) {
  const pts = [{ p0: startP0, p1: startP1 }];
  let p0 = startP0, p1 = startP1;
  for (let k = 0; k < 40; k++) {
    const g = grad(p0, p1);
    const norm = Math.hypot(g.g0, g.g1);
    if (norm < 0.012) break;
    p0 -= lr * g.g0;
    p1 -= lr * g.g1;
    pts.push({ p0, p1 });
    if (Math.abs(p0) > 4 || Math.abs(p1) > 4) break;
  }
  return pts;
}
function setDemoVisualsVisible(on) {
  demoVisualsOn = on;
