  path2DLine.visible = on;
  step3DGroup.visible = on;
  step2DGroup.visible = on;
  floatingReadoutLabel.entry.div.style.visibility = on && surfaceGroup.visible ? 'visible' : 'hidden';
}
function rebuildPath(revealCount = Infinity) {
  gdPath = computePath();
  const shown = gdPath.slice(0, Math.min(gdPath.length, revealCount));
  const pts3 = shown.map(p => surfLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.090));
  path3DLine.geometry.dispose();
  path3DLine.geometry = new THREE.BufferGeometry().setFromPoints(pts3);
  const pts2 = shown.map(p => heatLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.105));
  path2DLine.geometry.dispose();
  path2DLine.geometry = new THREE.BufferGeometry().setFromPoints(pts2);
  clearSteps(step3DGroup);
  clearSteps(step2DGroup);
  for (let i = 0; i < shown.length; i++) {
    const p = shown[i];
    const out = p.p0 < 0 || p.p0 > 2 || p.p1 < -1 || p.p1 > 1;
    const m3 = new THREE.Mesh(
      new THREE.SphereGeometry(0.022, 12, 8),
      new THREE.MeshBasicMaterial({ color: out ? 0xffd6a5 : 0x24d4c8, transparent: true, opacity: out ? 0.35 : 0.96 })
    );
    m3.position.copy(surfLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.108));
    step3DGroup.add(m3);
    const m2 = new THREE.Mesh(
      new THREE.CircleGeometry(0.022, 16),
      new THREE.MeshBasicMaterial({ color: out ? 0xffd6a5 : 0x24d4c8, transparent: true, opacity: out ? 0.35 : 0.96, side: THREE.DoubleSide })
    );
    m2.position.copy(heatLocal(clamp(p.p0, 0, 2), clamp(p.p1, -1, 1), 0.122));
    step2DGroup.add(m2);
  }
}
function updateCurrent(skipPath = false) {
  const L = loss(current.p0, current.p1);
  active3D.position.copy(surfLocal(current.p0, current.p1, 0.072));
  active2D.position.copy(heatLocal(current.p0, current.p1, 0.112));
