    elevationDeg: 0,
    rollDeg: 0,
    zoom: 1.78,
    target: [surfX + 0.05, 0.30, 0.05],
    heightFraction: 0.82
  });
}
function cameraForHeatmap() {
  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 90,
    elevationDeg: 0,
    rollDeg: 0,
    zoom: 2.18,
    target: [heatX, 0.02, 0.10],
    heightFraction: 0.84
  });
}

function applyViewMode(mode) {
  viewModeValue = mode;
  for (const b of document.querySelectorAll('#viewMode button')) b.classList.toggle('active', b.dataset.view === mode);
  surfaceGroup.visible = mode !== 'Heatmap';
  heatmapGroup.visible = mode !== '3D surface';
  setBucketVisible(surfaceLabels, mode !== 'Heatmap');
  setBucketVisible(heatLabels, mode !== '3D surface');
  if (demoVisualsOn) floatingReadoutLabel.entry.div.style.visibility = surfaceGroup.visible ? 'visible' : 'hidden';
  else floatingReadoutLabel.entry.div.style.visibility = 'hidden';

  controls.enabled = mode !== 'Heatmap';
  controls.enableRotate = false;
  controls.enablePan = true;
  controls.enableZoom = true;

  if (mode === '3D surface') cameraForSurface();
  else if (mode === 'Heatmap') cameraForHeatmap();
  else cameraForLinked();

  updateGroupLabels();
}
applyViewMode('Linked split');
setDemoVisualsVisible(false);

document.querySelectorAll('#viewMode button').forEach(btn => {
  btn.addEventListener('click', () => applyViewMode(btn.dataset.view));
});
document.getElementById('learningRate').addEventListener('input', e => {
  lr = Number(e.target.value);
  document.getElementById('lrVal').textContent = lr.toFixed(3);
  gdAnimating = false;
  if (demoVisualsOn) rebuildPath();
});

document.getElementById('gradientDescentRun').addEventListener('click', () => {
  setDemoVisualsVisible(true);
  gdAnimating = true;
  gdFrame = 1;
  rebuildPath(1);
  requestAnimationFrame(tickGD);
});

function tickGD() {
  if (!gdAnimating) return;
  gdFrame += 0.075;
  const idx = Math.min(gdPath.length - 1, Math.floor(gdFrame));
  if (gdPath[idx]) {
    current.p0 = clamp(gdPath[idx].p0, 0, 2);
    current.p1 = clamp(gdPath[idx].p1, -1, 1);
    updateCurrent(true);
    rebuildPath(idx + 1);
  }
  if (idx >= gdPath.length - 1) gdAnimating = false;
  if (gdAnimating) requestAnimationFrame(tickGD);
}

const dragRay = new THREE.Raycaster();
const dragNdc = new THREE.Vector2();
let dragging = false;
function ndcFromEvent(e) {
  const rect = canvas.getBoundingClientRect();
  dragNdc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragNdc.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
}
function hitToParameter(e, requireMarker) {
  ndcFromEvent(e);
  dragRay.setFromCamera(dragNdc, camera);
  const markerTargets = viewModeValue === 'Heatmap' ? [active2D] : viewModeValue === '3D surface' ? [active3D] : [active3D, active2D];
  const markerHits = dragRay.intersectObjects(markerTargets, false);
  if (requireMarker && !markerHits.length) return null;

  const targets = [];
  if (heatmapGroup.visible) targets.push(dragPlane2D);
  if (surfaceGroup.visible) targets.push(dragPlane3D);
  const hits = dragRay.intersectObjects(targets, false);
  if (!hits.length) return null;
  const h = hits[0];
  if (h.object === dragPlane3D) {
    const loc = surfaceGroup.worldToLocal(h.point.clone());
    return { p0: clamp(loc.x / SX + 1, 0, 2), p1: clamp(loc.z / SZ, -1, 1) };
  }
  const loc = heatmapGroup.worldToLocal(h.point.clone());
  return { p0: clamp(loc.x / HX + 1, 0, 2), p1: clamp(-loc.y / HY, -1, 1) };
}
canvas.addEventListener('pointerdown', e => {
  const p = hitToParameter(e, true);
  if (!p) return;
  dragging = true;
  gdAnimating = false;
  controls.enabled = false;
  current = p;
  updateCurrent();
  floatingReadoutLabel.entry.div.style.visibility = surfaceGroup.visible ? 'visible' : 'hidden';
  canvas.setPointerCapture?.(e.pointerId);
});
canvas.addEventListener('pointermove', e => {
  if (!dragging) return;
  const p = hitToParameter(e, false);
  if (!p) return;
  current = p;
  updateCurrent();
});
window.addEventListener('pointerup', () => {
  if (!dragging) return;
  dragging = false;
  controls.enabled = viewModeValue !== 'Heatmap';
  if (!demoVisualsOn) floatingReadoutLabel.entry.div.style.visibility = 'hidden';
});

const demoSteps = [
  { title: 'Inspect the loss bowl', state: { viewMode: '3D surface', learningRate: 0.03, showPath: false } },
  { title: 'Match surface height to contours', state: { viewMode: 'Heatmap', learningRate: 0.03, showPath: false } },
  { title: 'Slow, stable descent', state: { viewMode: 'Linked split', learningRate: 0.01, start: [0.40, 0.20], run: true } },
  { title: 'Overshoot and oscillation', state: { viewMode: 'Linked split', learningRate: 0.08, start: [0.40, 0.20], run: true } },
];
window.goToStep = function goToStep(i) {
  const s = demoSteps[i]?.state;
  if (!s) return;
  gdAnimating = false;
  lr = s.learningRate;
  const input = document.getElementById('learningRate');
  input.value = String(lr);
  document.getElementById('lrVal').textContent = lr.toFixed(3);
  if (s.start) current = { p0: s.start[0], p1: s.start[1] };
  updateCurrent();
  applyViewMode(s.viewMode);
  setDemoVisualsVisible(!!s.run);
  if (s.run) document.getElementById('gradientDescentRun').click();
};
document.querySelectorAll('[data-step]').forEach(btn => {
  btn.addEventListener('click', () => window.goToStep(Number(btn.dataset.step)));
});

updateGroupLabels();
// @FIGURE_CODE_END

